import arrow
from datetime import datetime

def test_dehumanize_locales():
    arw = arrow.utcnow()
    locales_to_test = ["fi", "fi-fi", "ne", "ne-np", "ee", "et", "zu", "zu-za"]

    for locale in locales_to_test:
        try:
            # We don't necessarily know the exact string that would work for each locale
            # but we want to make sure it doesn't raise the "not supported" ValueError.
            # Since we don't know the timeframes for these locales, 
            # we can try to use a generic one or just check if it gets past the locale check.
            # Actually, the easiest way to check if the locale is supported is to 
            # call dehumanize with any string. If it's not supported, it raises ValueError.
            # If it is supported, it might raise a different ValueError if the string is invalid,
            # but it won't be the "Dehumanize does not currently support the {locale} locale" one.

            try:
                arw.dehumanize("now", locale=locale)
            except ValueError as e:
                if "does not currently support the" in str(e):
                    print(f"Locale {locale} is NOT supported: {e}")
                    raise e
                else:
                    # This is expected if "now" is not a valid timeframe for the locale
                    # but the locale itself is supported.
                    print(f"Locale {locale} is supported (raised invalid string error: {e})")
            except Exception as e:
                print(f"Locale {locale} raised unexpected exception: {e}")
                raise e
            else:
                print(f"Locale {locale} is supported and 'now' worked.")

        except Exception as e:
            print(f"Failed for locale {locale}: {e}")
            raise e

if __name__ == "__main__":
    test_dehumanize_locales()
    print("All locales passed the support check!")
